CREATE TABLE IF NOT EXISTS `users` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `email` TEXT, `password_hash` TEXT, `role` TEXT, `full_name` TEXT, `city` TEXT, `province` TEXT, `postal_code` TEXT, `email_verified` INTEGER NOT NULL, `address` TEXT, `phone` TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS `index_users_email` ON `users` (`email`);
CREATE TABLE IF NOT EXISTS `restaurants` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `manager_id` INTEGER NOT NULL, `name` TEXT, `city` TEXT, `province` TEXT, `postal_code` TEXT, `phone` TEXT, `cuisine_type` TEXT, `description` TEXT, `image_uri` TEXT, FOREIGN KEY(`manager_id`) REFERENCES `users`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE UNIQUE INDEX IF NOT EXISTS `index_restaurants_manager_id` ON `restaurants` (`manager_id`);
CREATE TABLE IF NOT EXISTS `orders` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `customer_id` INTEGER NOT NULL, `restaurant_id` INTEGER, `restaurant_name` TEXT, `restaurant_address` TEXT, `restaurant_image_uri` TEXT, `placed_at` INTEGER NOT NULL, `item_count` INTEGER NOT NULL, `total` REAL NOT NULL, `status` TEXT, `pickup_time` TEXT, `is_delivery` INTEGER NOT NULL, `delivery_address` TEXT, FOREIGN KEY(`customer_id`) REFERENCES `users`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`restaurant_id`) REFERENCES `restaurants`(`id`) ON UPDATE NO ACTION ON DELETE SET NULL );
CREATE INDEX IF NOT EXISTS `index_orders_customer_id` ON `orders` (`customer_id`);
CREATE INDEX IF NOT EXISTS `index_orders_restaurant_id` ON `orders` (`restaurant_id`);
CREATE TABLE IF NOT EXISTS `order_items` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `order_id` INTEGER NOT NULL, `food_item_id` INTEGER NOT NULL, `name` TEXT, `unit_price` REAL NOT NULL, `quantity` INTEGER NOT NULL, FOREIGN KEY(`order_id`) REFERENCES `orders`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_order_items_order_id` ON `order_items` (`order_id`);
CREATE TABLE IF NOT EXISTS `notifications` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `customer_id` INTEGER NOT NULL, `order_id` INTEGER NOT NULL, `status` TEXT, `created_at` INTEGER NOT NULL, FOREIGN KEY(`customer_id`) REFERENCES `users`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`order_id`) REFERENCES `orders`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_notifications_customer_id` ON `notifications` (`customer_id`);
CREATE INDEX IF NOT EXISTS `index_notifications_order_id` ON `notifications` (`order_id`);
CREATE TABLE IF NOT EXISTS `food_items` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `restaurantId` INTEGER NOT NULL, `name` TEXT, `description` TEXT, `category` TEXT, `originalPrice` REAL NOT NULL, `discountedPrice` REAL NOT NULL, `quantityLeft` INTEGER NOT NULL, `availableUntil` TEXT, `available` INTEGER NOT NULL, `imageUri` TEXT);
